fn is_palindrome(text: Vec<char>) -> bool {
    let mut left = 0;
    let mut right = text.len().saturating_sub(1); // Use saturating_sub to avoid underflow

    while left < right {
        // Get the left character and convert to lowercase if it's uppercase
        let left_char = text[left].to_ascii_lowercase();
        // Get the right character and convert to lowercase if it's uppercase
        let right_char = text[right].to_ascii_lowercase();

        // Compare the characters
        if left_char != right_char {
            return false; // Mismatch found
        }

        // Move the pointers towards the center
        left += 1;
        right = right.saturating_sub(1); // Use saturating_sub to avoid underflow
    }

    true // All characters matched
}